import base64
import math
from io import BytesIO
from typing import List

from PIL import Image
from openai import OpenAI


def image2b64(img_path):
    with open(img_path, "rb") as image_file:
        return base64.b64encode(image_file.read()).decode('utf-8')
    
def pil_img2b64(img_pil):
    buffered = BytesIO()
    img_pil.save(buffered, format="PNG")
    return base64.b64encode(buffered.getvalue()).decode('utf-8')

TEMPLATE = r'''{instruction}

You will act as a professional image quality evaluator. Your task is to be given two edited images, both of which are generated by the same input image and editing prompt, and then evaluate which image has a better generation quality considering the following two criteria:

(1) Editing Capability: How well does the image reflect the requested edits? Does it successfully implement the changes described in the prompt?

(2) Keeping Capability: How well does the image preserve the original content from the reference image? Does it maintain the key details, structure, and style of the original while making the requested edits?



Is [Image 2] better than [Image 1]? Please answer only "Yes" or "No". Do not provide any additional explanations.
'''

class EditRefRM(object):
    def __init__(self, url):
        """
        url-> 127.0.0.1:8080
        """
        self.url = f"http://{url}/v1"
        print(f'EditRefRM url:{self.url}')
        self.client = OpenAI(
            api_key="EMPTY",
            base_url=self.url,
            timeout=3600
        )

    def build_message(self, src_image, prompt, ref_image, gen_image):
        src_image = pil_img2b64(src_image)
        ref_image = pil_img2b64(ref_image)
        gen_image = pil_img2b64(gen_image)
        prompt = TEMPLATE.format(instruction=prompt)
        # print(f'image edit prompt={prompt}')
        message = [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": f"[Input Image]:"},
                    {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{src_image}"}},
                    {"type": "text", "text": f"[Image 1]:"},
                    {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{ref_image}"}},
                    {"type": "text", "text": f"\n[Image 2]:"},
                    {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{gen_image}"}},
                    {"type": "text", "text": f"\n[Edit Prompt]: {prompt}"},
                ]
            }
        ]

        return message

    def compute_reward(self, response, strategy="prob"):
        '''
        parse:
            response: the response object from vLLM
            strategy: "logprob", "yes_prob"
        return: 
            reward: the computed reward value or None if cannot compute
        '''
        logprobs = response.choices[0].logprobs.content[0].top_logprobs
        yes_prob = None
        for lp in logprobs:
            # print(f'token={lp.token}, logprob={lp.logprob}, prob={math.exp(lp.logprob)}')
            if lp.token.strip().lower() == "yes":
                if yes_prob is not None:
                    yes_prob += math.exp(lp.logprob)
                else:
                    yes_prob = math.exp(lp.logprob)

        if strategy == "logprob":
            return math.log(yes_prob) if yes_prob else None
        elif strategy == "prob":
            return yes_prob
        else:
            raise ValueError(f"Unknown strategy for computing reward: {strategy}")
    
    def __call__(
            self,
            src_images: List[Image.Image],
            prompts: List[str],
            ref_images: List[Image.Image],
            gen_images: List[Image.Image],
    ):
        score_list = []
        succe_list = []
        for src_image, prompt, ref_image, gen_image in zip(src_images, prompts, ref_images, gen_images):
            score, succe = self.single_call(src_image, prompt, ref_image, gen_image)
            # print(f'***************{self.url=}***************\n{src_image=}\n, {prompt=}\n, {ref_image=}\n, {gen_image=}\n lucas debug edit_ref_rm:{score=},{succe=}')
            score_list.append(score)
            succe_list.append(succe)

        # print(f'lucas debug {self.url=}, edit_ref_rm:{score_list=},{succe_list=}')

        return score_list, succe_list

    def single_call(
            self,
            src_image: Image.Image,
            prompt: str,
            ref_image: Image.Image,
            gen_image: Image.Image,
    ):
        max_retry = 3
        retry = 0
        while retry < max_retry:
            retry += 1
            try:
                message = self.build_message(src_image, prompt, ref_image, gen_image)
                response = self.client.chat.completions.create(
                    model="Qwen3-VL-32B-Instruct",
                    messages=message,
                    max_tokens=1024,
                    logprobs=True,
                    top_logprobs=20,
                )
                score = self.compute_reward(response)
                return score, True
            except Exception as e:
                print(f"{self.url=}, request EditRM error:{e}, retry={retry}/{max_retry}")

        return 0, False


